5:  describe("quote — base premiums", () => {
74:  describe("quote — building block of 3 alike components", () => {
176:  describe("quote — item-scoped modifiers", () => {
266:  describe("quote — policy-scoped modifiers", () => {
327:  describe("quote — rounding", () => {
359:  describe("quote — integration examples", () => {
403:  describe("quote — errors", () => {
414:  describe("claim — standard reimbursement", () => {
